queries.cql:
// CrowdStrike CQL for Single-Code Billing Concentration Detection
// Flags providers where one HCPCS code exceeds 80% of total claims
| groupBy(provider_npi, function=[
    count(as=total_claims),
    sum(billed_amount, as=total_billed),
    count(field=beneficiary_id, distinct=true, as=unique_beneficiaries),
    count(field=hcpcs_code, distinct=true, as=unique_codes)
  ])
| total_claims >= 500
| code_diversity := round(unique_codes / total_claims * 10000) / 10000
| code_diversity < 0.05
| alert_type := "SINGLE_CODE_CONCENTRATION"
| sort(total_billed, order=desc)

